node -e "
const buf = require('fs').readFileSync('/workspace/world.db');
const text = buf.toString('utf8');

// Search broadly around all onboarding/olivia mentions
const terms = ['onboarding', 'olivia', 'ethan', 'equipment'];
const offsets = new Set();
for (const t of terms) {
  let idx = 0;
  while ((idx = text.toLowerCase().indexOf(t, idx)) !== -1) {
    offsets.add(idx);
    idx += t.length;
  }
}
// Print context around each match
const sorted = [...offsets].sort((a,b) => a-b);
for (const o of sorted) {
  const start = Math.max(0, o - 200);
  const end = Math.min(text.length, o + 500);
  const snippet = text.slice(start, end).replace(/[\x00-\x1f]/g, ' ');
  console.log('--- offset', o, '---');
  console.log(snippet);
  console.log();
}
"
